package br.vbrasfoot.hooks;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import jdk.internal.org.objectweb.asm.*;

/** Generated bytecode is parsed only, never loaded/executed. */
public final class MutationSurfaceInventorySelfTest {
    private static int checks;
    private static void check(boolean value, String label) { if (!value) throw new AssertionError(label); checks++; }
    private static byte[] fixture(String name, String parent) {
        var out = new ClassWriter(0); out.visit(Opcodes.V1_8, Opcodes.ACC_PUBLIC, name, null, parent, null);
        out.visitMethod(Opcodes.ACC_PUBLIC | Opcodes.ACC_NATIVE, "external", "()V", null, null).visitEnd();
        var method = out.visitMethod(Opcodes.ACC_PUBLIC, "read", "()V", null, null); method.visitCode();
        method.visitFieldInsn(Opcodes.PUTFIELD, "best/ah", "nb", "J");
        method.visitFieldInsn(Opcodes.PUTFIELD, "best/ah", "nx", "Lbest/C;");
        method.visitFieldInsn(Opcodes.PUTFIELD, "best/C", "dK", "J");
        method.visitFieldInsn(Opcodes.PUTFIELD, "best/C", "dL", "I");
        method.visitFieldInsn(Opcodes.PUTFIELD, "other", "nb", "J");
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/reflect/Field", "setLong", "(Ljava/lang/Object;J)V", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "sun/misc/Unsafe", "putLong", "(Ljava/lang/Object;JJ)V", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "jdk/internal/misc/Unsafe", "compareAndSetInt", "(Ljava/lang/Object;JII)Z", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "com/esotericsoftware/reflectasm/FieldAccess", "set", "(Ljava/lang/Object;ILjava/lang/Object;)V", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/reflect/Method", "invoke", "(Ljava/lang/Object;[Ljava/lang/Object;)Ljava/lang/Object;", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/invoke/VarHandle", "set", "(Ljava/lang/Object;J)V", false);
        method.visitMethodInsn(Opcodes.INVOKESTATIC, "java/lang/System", "loadLibrary", "(Ljava/lang/String;)V", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/reflect/Field", "setAccessible", "(Z)V", false);
        method.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/reflect/Field", "getLong", "(Ljava/lang/Object;)J", false);
        method.visitInvokeDynamicInsn("own", "()V", new Handle(Opcodes.H_INVOKESTATIC, "fixture/Bootstrap", "link", "()V", false));
        method.visitInsn(Opcodes.RETURN); method.visitMaxs(0, 1); method.visitEnd(); out.visitEnd(); return out.toByteArray();
    }
    private static Path archive(Path root, String name, byte[] code) throws IOException {
        Path file = root.resolve(name); try (var zip = new ZipOutputStream(Files.newOutputStream(file))) {
            zip.putNextEntry(new ZipEntry("own/Fixture.class")); zip.write(code); zip.closeEntry();
            zip.putNextEntry(new ZipEntry("ignored.jar")); zip.write(new byte[]{1, 2}); zip.closeEntry();
        } return file;
    }
    public static void main(String[] args) throws Exception {
        Path root = Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("java.io.tmpdir"), "opencode")), "surface-inventory-");
        Path file = archive(root, "owned.jar", fixture("own/Fixture", "com/esotericsoftware/kryo/Serializer"));
        var report = MutationSurfaceInventory.scan(file);
        check(report.classes() == 1 && report.instructions() == 16, "all instructions counted, nested opaque archive not executed or scanned");
        check(report.equals(MutationSurfaceInventory.scan(file)), "deterministic report against exact archive digest");
        check(!report.universalMutationCoverage(), "even complete scan is not universal runtime coverage");
        for (var kind : MutationSurfaceInventory.Kind.values()) {
            long expected = kind == MutationSurfaceInventory.Kind.DIRECT_FINANCE_WRITE ? 4
                    : kind == MutationSurfaceInventory.Kind.UNSAFE_WRITE || kind == MutationSurfaceInventory.Kind.DYNAMIC_CODE ? 2 : 1;
            check(report.sites().stream().filter(site -> site.kind() == kind).count() == expected, "exact generated site classification: " + kind);
        }
        check(report.sites().stream().noneMatch(site -> site.target().contains("setAccessible") || site.target().contains("getLong")), "metadata access and reads not mislabeled as financial writes");
        boolean immutable = false; try { report.sites().clear(); } catch (UnsupportedOperationException expected) { immutable = true; }
        check(immutable, "report cannot be mutated after scan");
        for (byte[] invalid : List.of(new byte[]{1, 2, 3}, new byte[2 * 1024 * 1024 + 1])) {
            boolean refused = false; try { MutationSurfaceInventory.scan(archive(root, "bad-" + invalid.length + ".jar", invalid)); } catch (IOException expected) { refused = true; }
            check(refused, "malformed/oversized member refuses entire inventory");
        }
        var onEdt = new java.util.concurrent.atomic.AtomicReference<Throwable>();
        javax.swing.SwingUtilities.invokeAndWait(() -> { try { MutationSurfaceInventory.scan(file); } catch (Throwable expected) { onEdt.set(expected); } });
        check(onEdt.get() instanceof IOException, "offline disk inventory refused on EDT");
        System.out.println("PASS: " + checks + " offline mutation surface inventory checks; own bytecode only, fixture " + root);
    }
}
